       mapView.onLowMemory();
   }

   private static class Data {
       private static final String[] STYLES = new String[]{
               Style.NBMAP_STREETS,
               Style.OUTDOORS,
               Style.LIGHT,
               Style.DARK,
               Style.SATELLITE,
