        if(sender.state == UIGestureRecognizer.State.began){
            let point = sender.location(in: sender.view)
            let coordinate = nbMapView.convert(point, toCoordinateFrom: nbMapView)
            points.append(coordinate)
            drawPolyline()
        }
    }

